import { useCallback, useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { api, download, forgetStartupToken, setCSRF, streamEvents } from './api';
import { ProjectControls, ModelPresetControls, ExecutionSettings, TraceRegister, RetestControl, ROLE_LABELS, defaultExtensions } from './extensions';
import { getLang, labels, locale, setLang, t, useLang } from './i18n';
import type { AuthProfile, Budget, Capabilities, Finding, ModelProfile, Provider, Run, RunInput, RunExtensions, Session, TestCase } from './types';

const STAGES = () => [['intake',t('接收','Intake')],['preflight',t('預檢','Preflight')],['whitebox',t('白箱審查','White-box review')],['adjudication',t('證據仲裁','Adjudication')],['threat_model',t('威脅建模','Threat modeling')],['case_design',t('測試設計','Test design')],['blackbox',t('黑箱驗證','Black-box verification')],['report',t('產出報告','Report')],['complete',t('完成','Complete')]];
const STATUS: Record<string,string> = labels({created:['待啟動','Not started'],awaiting_approval:['待核准案例','Cases awaiting approval'],running:['執行中','Running'],cancelling:['停止中','Stopping'],cancelled:['已停止','Stopped'],completed:['已完成','Completed'],complete:['已完成','Completed'],sealed:['初審已封存','Initial review sealed'],incomplete:['未完整完成','Incomplete'],blocked:['受阻','Blocked'],failed:['執行失敗','Failed'],pass:['未觀測到違規','No violation observed'],fail:['觀測到違規','Violation observed'],inconclusive:['證據不足','Insufficient evidence'],execution_error:['執行錯誤','Execution error'],outcome_unknown:['結果不明','Outcome unknown']});
const STATES: Record<string,string> = labels({hypothesis:['待驗證假設','Unverified hypothesis'],corroborated_static:['靜態佐證','Statically corroborated'],validated_dynamic:['動態驗證','Dynamically validated'],refuted:['已排除','Refuted'],inconclusive:['尚無定論','Inconclusive']});
const SEVERITY: Record<string,string> = labels({critical:['嚴重','Critical'],high:['高','High'],medium:['中','Medium'],low:['低','Low'],info:['資訊','Info']});
const PROVIDERS: Record<Provider,string> = labels<Provider>({demo:['本地合成示範','Local synthetic demo'],openai:['OpenAI','OpenAI'],anthropic:['Anthropic Claude','Anthropic Claude'],nvidia_nim:['NVIDIA NIM','NVIDIA NIM'],openai_compatible:['相容 API／本地模型','Compatible API / local model']});
const formatNumber = (n: number | undefined) => new Intl.NumberFormat(locale()).format(n ?? 0);
const short = (text: string | undefined) => text ? `${text.slice(0,10)}${text.length > 10 ? '…' : ''}` : t('未記錄','Not recorded');
const date = (value: string) => { const d = new Date(value); return Number.isNaN(d.getTime()) ? value : d.toLocaleString(locale(), {month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}); };
const stringify = (v: unknown): string => typeof v === 'string' ? v : JSON.stringify(v,null,2) ?? '—';
function record(value: unknown): Record<string,unknown> { return value !== null && typeof value === 'object' && !Array.isArray(value) ? value as Record<string,unknown> : {}; }
function executionResult(ex: Record<string,unknown>) { return Object.keys(record(ex.result)).length ? record(ex.result) : ex; }
function Icon({name,size=20}: {name:string;size?:number}) {
  const paths: Record<string,ReactNode> = {
    shield:<><path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6Z"/><path d="m8 12 3 3 5-6"/></>,
    grid:<><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></>,
    plus:<path d="M12 5v14M5 12h14"/>, play:<path d="m8 4 12 8-12 8Z"/>, stop:<rect x="5" y="5" width="14" height="14" rx="2"/>,
    arrow:<path d="M5 12h14m-5-5 5 5-5 5"/>, check:<path d="m5 12 4 4L19 6"/>, refresh:<><path d="M20 11a8 8 0 0 0-14-5L3 9m0-5v5h5M4 13a8 8 0 0 0 14 5l3-3m0 5v-5h-5"/></>,
    chip:<><rect x="6" y="6" width="12" height="12" rx="3"/><rect x="9" y="9" width="6" height="6" rx="1"/><path d="M9 3v3m6-3v3m-6 12v3m6-3v3M3 9h3m-3 6h3m12-6h3m-3 6h3"/></>,
    lock:<><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/></>,
    file:<><path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9Z"/><path d="M14 3v6h6M8 13h8m-8 4h5"/></>,
    pulse:<path d="M2 12h5l3-8 4 16 3-8h5"/>, download:<><path d="M12 3v12m-5-5 5 5 5-5M4 16v4h16v-4"/></>,
    alert:<><path d="m12 3 10 18H2Z"/><path d="M12 9v5m0 3v.2"/></>, link:<><path d="m9 15 6-6m-7 3-2 2a4 4 0 0 0 6 6l2-2m-4-12 2-2a4 4 0 0 1 6 6l-2 2"/></>,
    code:<><path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-16-2 20"/></>, close:<path d="m6 6 12 12M6 18 18 6"/>, chevron:<path d="m9 5 7 7-7 7"/>,
  };
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.65" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name] ?? paths.file}</svg>;
}
function Badge({value,children}: {value?:string;children?:ReactNode}) { return <span className={`badge ${value ?? ''}`}>{children ?? STATUS[value ?? ''] ?? value}</span>; }
function Empty({title,children}: {title:string;children?:ReactNode}) { return <div className="empty"><span className="empty-icon"><Icon name="file" size={25}/></span><h3>{title}</h3><p>{children}</p></div>; }
function SafeText({value}: {value:unknown}) { return <pre className="safe-text">{stringify(value)}</pre>; }
function Panel({title,eyebrow,children,action}: {title:string;eyebrow?:string;children:ReactNode;action?:ReactNode}) { return <section className="panel"><div className="panel-heading"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h2>{title}</h2></div>{action}</div>{children}</section>; }

export default function App() {
  const lang = useLang();
  const [session,setSession] = useState<Session|null>(null);
  const [capabilities,setCapabilities] = useState<Capabilities|null>(null);
  const [runs,setRuns] = useState<Run[]>([]);
  const [selected,setSelected] = useState<Run|null>(null);
  const [view,setView] = useState<'runs'|'create'|'capabilities'>('runs');
  const [tab,setTab] = useState('overview');
  const [error,setError] = useState('');
  const [busy,setBusy] = useState('');
  const [connecting,setConnecting] = useState(true);
  const syncRun = useCallback((run:Run) => {setSelected(run); setRuns(prev => [run,...prev.filter(r=>r.id!==run.id)]);},[]);
  const connect = useCallback(async () => {
    setConnecting(true); setError('');
    try {
      const s = await api<Session>('/session'); setCSRF(s.csrf_token); setSession(s);
      const [caps,list] = await Promise.all([api<Capabilities>('/capabilities'),api<{runs:Run[]}>('/runs')]);
      setCapabilities(caps); setRuns(list.runs);
      if (list.runs.length) setSelected(await api<Run>(`/runs/${encodeURIComponent(list.runs[0].id)}`));
    } catch (e) {setError(e instanceof Error ? e.message : t('無法連線至本地服務','Cannot connect to the local service'));}
    finally {setConnecting(false);}
  },[]);
  const logout = useCallback(async () => {
    try {await api('/session/logout',{});} catch {/* An expired session is already ended. */}
    forgetStartupToken(); setCSRF(''); setSession(null); setRuns([]); setSelected(null); setCapabilities(null);
    setError(t('已登出。請用服務啟動時印出的網址重新開啟。','Signed out. Reopen the console with the URL printed when the service started.'));
  },[]);
  useEffect(()=>{void connect();},[connect]);
  useEffect(()=>{
    if (!selected || !['running','cancelling'].includes(selected.status)) return;
    let active = true;
    let fetching = false;
    const refresh = async () => {
      if (fetching) return; fetching = true;
      try { const run = await api<Run>(`/runs/${encodeURIComponent(selected.id)}`); if(active) syncRun(run); }
      catch(e) { if(active) setError(t(`更新中斷：${e instanceof Error?e.message:'連線失敗'}。重新連線後可查看已保存進度。`,`Updates stopped: ${e instanceof Error?e.message:'connection failed'}. Reconnect to see the saved progress.`)); }
      finally {fetching = false;}
    };
    const stream = new AbortController();
    // Polling below keeps the view current if the event stream drops.
    streamEvents(`/runs/${encodeURIComponent(selected.id)}/events`,name=>{void refresh();if(name==='done'||name==='expired')stream.abort();},stream.signal).catch(()=>{});
    const timer = window.setInterval(refresh,2500);
    return ()=>{active=false;clearInterval(timer);stream.abort();};
  },[selected?.id,selected?.status,syncRun]);
  async function selectRun(run:Run) {setBusy('load');setError('');try {syncRun(await api<Run>(`/runs/${encodeURIComponent(run.id)}`));setView('runs');setTab('overview');}catch(e){setError(String(e));}finally{setBusy('');}}
  async function action(kind:RunAction) {if(!selected)return;let body={};if(kind==='approve-cases'){const count=selected.cases.filter(c=>c.designed_by==='model').length;if(!window.confirm(t(`將送出 ${selected.cases.length} 個已封存案例，其中 ${count} 個由模型設計。請先在「追溯」分頁核對每個案例的方法、路徑、標頭、本文與身分；核准只適用於目前這組案例。`,`This sends ${selected.cases.length} sealed cases, ${count} of them designed by a model. First check each case's method, path, headers, body and identity on the Trace tab; the approval covers only this set of cases.`)))return;body={receipt:selected.gate_receipts?.cases??''};}if(kind==='reconcile'){const attestation=window.prompt(t('監督程式未能確認工作容器已移除。請說明你如何確認已清理或重設測試環境。這段說明會存為證據；此執行之後不能再恢復，請以新的執行繼續。','The supervisor could not confirm that the worker container was removed. Describe how you confirmed the test environment was cleaned up or reset. This statement is stored as evidence; this run cannot be resumed afterwards, so continue with a new run.'))?.trim();if(!attestation)return;body={attestation};}setBusy(kind);setError('');try {syncRun(await api<Run>(`/runs/${encodeURIComponent(selected.id)}/${kind}`,body));}catch(e){setError(e instanceof Error?e.message:String(e));}finally{setBusy('');}}
  async function createRun(input:RunInput) {
    setBusy('create');setError('');
    try {const run=await api<Run>('/runs',input);syncRun(run);setView('runs');setTab('overview');syncRun(await api<Run>(`/runs/${encodeURIComponent(run.id)}/start`,{}));}
    catch(e){setError(e instanceof Error?e.message:String(e));throw e;}
    finally{setBusy('');}
  }
  return <div className="app-shell">
    <aside className="sidebar">
      <a className="brand" href="#" onClick={e=>{e.preventDefault();setView('runs');}}><span className="brand-mark"><Icon name="shield" size={25}/></span><span>Vibe Audit<small>{t('安全驗證工作台','Security Workbench')}</small></span><span className="version">α</span></a>
      <div className="workspace-tag"><span className="live-dot"/> LOCAL WORKSPACE</div>
      <nav aria-label={t('主要導覽','Main navigation')}><button className={view==='runs'?'nav active':'nav'} onClick={()=>setView('runs')}><Icon name="grid"/>{t('評估工作台','Assessments')}<span className="nav-count">{runs.length}</span></button><button className={view==='create'?'nav active':'nav'} onClick={()=>setView('create')}><Icon name="plus"/>{t('新建評估','New assessment')}</button><button className={view==='capabilities'?'nav active':'nav'} onClick={()=>setView('capabilities')}><Icon name="chip"/>{t('工具與執行環境','Tools and runtime')}</button></nav>
      <div className="sidebar-label">{t('最近的評估','Recent assessments')}</div>
      <div className="recent-list">{runs.slice(0,8).map(run=><button key={run.id} className={`recent ${selected?.id===run.id&&view==='runs'?'selected':''}`} onClick={()=>void selectRun(run)}><span className={`status-dot ${run.status}`}/><span className="recent-content"><strong>{run.name}</strong><small>{run.mode==='demo'?t('示範','Demo'):t('實際評估','Live assessment')} · {date(run.created_at)}</small></span></button>)}{!runs.length&&<p className="sidebar-empty">{t('每一次評估，都留下','Every assessment leaves')}<br/>{t('可追溯的證據。','traceable evidence.')}</p>}</div>
      <div className="sidebar-footer"><Icon name="lock" size={17}/><span>{t('執行於本機','Runs on this machine')}<small>{t('資料送往模型依你的設定','Data goes to models only as you configure')}</small></span></div>
    </aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumb">{t('工作空間','Workspace')} <Icon name="chevron" size={13}/><strong>{view==='create'?t('新建評估','New assessment'):view==='capabilities'?t('工具與執行環境','Tools and runtime'):t('評估工作台','Assessments')}</strong></div><div className="topbar-status"><button type="button" className="button secondary small lang-toggle" lang={lang==='en'?'zh-Hant':'en'} aria-label={t('切換為英文介面','Switch to the Chinese interface')} onClick={()=>setLang(lang==='en'?'zh-Hant':'en')}>{lang==='en'?'中文':'English'}</button><span className={session?'live-dot':'live-dot off'}/>{connecting?t('連線中','Connecting'):session?t('本地服務已連線','Local service connected'):t('服務未連線','Service not connected')}<button className="icon-button" aria-label={t('重新連線並更新','Reconnect and refresh')} title={t('重新連線並更新','Reconnect and refresh')} onClick={()=>void connect()} disabled={connecting}><Icon name="refresh" size={16}/></button>{session&&<button className="button secondary small" title={t('結束這個工作階段；之後要用啟動網址重新開啟','End this session; reopen with the startup URL afterwards')} onClick={()=>void logout()}>{t('登出','Sign out')}</button>}</div></header>
      <main>
        {error&&<div className="notice error" role="alert"><Icon name="alert"/><div><strong>{t('這次操作尚未完成','This action did not complete')}</strong><p>{error}</p></div><button className="icon-button" aria-label={t('關閉提示','Dismiss notice')} onClick={()=>setError('')}><Icon name="close" size={16}/></button></div>}
        {!session&&!connecting?<div className="connection-card"><Icon name="pulse" size={38}/><h1>{t('等待本地服務','Waiting for the local service')}</h1><p>{t('先啟動 Vibe Audit 後端，並開啟它在終端機印出的含權杖網址。評估與證據會保存在你的本地工作空間。','Start the Vibe Audit backend, then open the URL with the token that it printed in the terminal. Assessments and evidence are stored in your local workspace.')}</p><button className="button primary" onClick={()=>void connect()}><Icon name="refresh" size={17}/>{t('重新連線','Reconnect')}</button><code>API · {import.meta.env.DEV?t('127.0.0.1:8000（開發模式經 Vite 代理）','127.0.0.1:8000 (through the Vite proxy in development)'):window.location.host||t('本機服務','Local service')}</code></div>:view==='create'?<CreateForm onCreate={createRun} busy={busy==='create'} connected={!!session}/>:view==='capabilities'?<CapabilitiesView capabilities={capabilities} session={session}/>:<>
          <div className="page-heading"><div><div className="eyebrow">EVIDENCE BEFORE CONFIDENCE</div><h1>{selected?selected.name:t('讓安全，有跡可循。','Make security traceable.')}</h1><p>{selected?t('從獨立白箱審查，到威脅導向驗證。每個結論都連回證據。','From independent white-box review to threat-driven verification. Every conclusion links back to evidence.'):t('先讀懂程式，再建立威脅模型，最後驗證真正的風險。','Understand the code first, then build the threat model, and finally verify the real risks.')}</p></div><button className="button primary" onClick={()=>setView('create')}><Icon name="plus" size={18}/>{t('新建評估','New assessment')}</button></div>
          {selected?<RunDetail run={selected} tab={tab} setTab={setTab} action={action} busy={busy} onCreated={syncRun}/>:<><div className="welcome-grid"><div className="welcome-main"><div className="orbit-graphic"><span className="orbit o1"/><span className="orbit o2"/><span className="orbit o3"/><span className="center-shield"><Icon name="shield" size={42}/></span><span className="orbit-node n1"><Icon name="code" size={18}/></span><span className="orbit-node n2"><Icon name="chip" size={18}/></span><span className="orbit-node n3"><Icon name="file" size={18}/></span></div><span className="eyebrow">MULTI-MODEL · LOCAL-FIRST</span><h2>{t('不同模型，獨立思考。','Different models, independent judgment.')}<br/>{t('共同依據，是證據。','The common ground is evidence.')}</h2><p>{t('一位指揮官協調三位審查員。各自完成初審後，再彙整工具結果與歧見，將威脅逐一轉為可驗證的測試。','One commander coordinates three reviewers. After each finishes an initial review, tool results and disagreements are combined and each threat becomes a verifiable test.')}</p><button className="button primary" onClick={()=>setView('create')}>{t('開始第一個評估','Start your first assessment')}<Icon name="arrow" size={17}/></button></div><div className="welcome-steps">{[['01',t('獨立白箱審查','Independent white-box review'),t('在同一份程式快照上，保留每個模型的判斷。','Keep each model\'s judgment on the same code snapshot.'),'code'],['02',t('威脅模型先行','Threat model first'),t('記錄資產、信任邊界與應被維持的安全條件。','Record assets, trust boundaries and the security conditions that must hold.'),'shield'],['03',t('用實際觀測驗證','Verify with real observations'),t('案例、執行與發現串成一條完整證據鏈。','Cases, executions and findings form one complete evidence chain.'),'link']].map(([n,title,desc,icon])=><div className="welcome-step" key={n}><span className="step-number">{n}</span><Icon name={icon}/><h3>{title}</h3><p>{desc}</p></div>)}</div></div><div className="notice subtle"><Icon name="file"/><p>{t('第一次使用？新建評估中的「合成示範」會在本地執行完整流程，不需模型金鑰，也不會對外發送測試請求。','First time here? The Synthetic demo under New assessment runs the whole flow locally, with no model keys and no outbound test requests.')}</p></div></>}
        </>}
      </main><footer className="main-footer"><span>VIBE AUDIT / LOCAL SECURITY WORKBENCH</span><span>{t('未發現違規 ≠ 已證明安全','No violation found ≠ proven secure')}</span></footer>
    </div>
  </div>;
}

// Mirrors the backend's resume refusals, so the console never offers a resume that cannot succeed.
const resumable=(run:Run)=>!run.workers_pending_cleanup&&!run.usage_unknown&&!run.deployment_changed&&!run.executions.some(e=>e.status==='outcome_unknown'||e.target_state_confirmed===false);
const REPORT_FORMATS = () => [['markdown','Markdown','md'],['json',t('完整 JSON','Full JSON'),'json'],['sarif','SARIF','sarif']] as const;
function ReportMenu({run}: {run:Run}) {
  const [error,setError] = useState('');
  async function save(format:string,extension:string) {setError('');try {await download(`/runs/${encodeURIComponent(run.id)}/report?format=${format}&lang=${getLang()}`,`vibe-audit-${run.id.slice(0,8)}.${extension}`);}catch(e){setError(t(`匯出失敗：${e instanceof Error?e.message:String(e)}`,`Export failed: ${e instanceof Error?e.message:String(e)}`));}}
  return <details className="download-menu"><summary className="button secondary small"><Icon name="download" size={15}/>{t('匯出報告','Export report')}</summary><div>{REPORT_FORMATS().map(([format,label,extension])=><button type="button" key={format} onClick={()=>void save(format,extension)}>{label}<Icon name="download" size={13}/></button>)}{error&&<p className="download-error" role="alert">{error}</p>}</div></details>;
}
type RunAction = 'start'|'cancel'|'resume'|'reconcile'|'approve-cases';
function RunDetail({run,tab,setTab,action,busy,onCreated}: {run:Run;tab:string;setTab:(tab:string)=>void;action:(kind:RunAction)=>Promise<void>;busy:string;onCreated?:(run:Run)=>void}) {
  const [focusEvidence,setFocusEvidence]=useState('');
  const stageIndex=STAGES().findIndex(([id])=>id===run.stage);
  const findings=run.findings??[];
  const threats=run.threat_model?.threats??[];
  const dynamic=findings.filter(f=>f.state==='validated_dynamic').length;
  const events=run.events??[];
  return <>
    <div className={`run-banner ${run.mode}`}><div><span className="banner-icon"><Icon name={run.mode==='demo'?'chip':'lock'} size={20}/></span><div><strong>{run.mode==='demo'?t('合成示範 · 不是實際安全評估','Synthetic demo · not a real security assessment'):t('實際評估 · 僅在設定範圍內執行','Live assessment · runs only within the configured scope')}</strong><p>{run.mode==='demo'?t('結果來自本地合成情境；沒有呼叫真實 LLM，也不代表任何模型的偵測能力。','Results come from a local synthetic scenario; no real LLM was called, and nothing here reflects any model\'s detection ability.'):run.manifest.data_policy==='local_only'?t('模型請求限本地端點；測試僅前往已設定的隔離環境。','Model requests stay on local endpoints; tests go only to the configured isolated environment.'):t('已允許雲端模型；程式內容可能送往你明確允許的模型端點。','Cloud models are allowed; code may be sent to the model endpoints you explicitly allowed.')}</p></div></div><Badge value={run.status}/></div>
    <div className="run-toolbar"><div className="run-meta"><span><Icon name="file" size={14}/><code>{short(run.id)}</code></span><span>{t('建立於','Created')} {date(run.created_at)}</span>{run.manifest.deployment_id&&<span>{t('部署','Deployment')} <code>{run.manifest.deployment_id}</code></span>}</div><div className="toolbar-actions"><RetestControl key={run.id} run={run} onCreated={onCreated}/>{run.status==='created'&&<button className="button primary small" disabled={!!busy} onClick={()=>void action('start')}><Icon name="play" size={14}/>{t('啟動','Start')}</button>}{run.status==='awaiting_approval'&&<button className="button primary small" disabled={!!busy} title={t('模型設計的案例要經你核准後才會送往目標','Model-designed cases go to the target only after you approve them')} onClick={()=>void action('approve-cases')}><Icon name="check" size={14}/>{t('核准案例並執行','Approve cases and run')}</button>}{['running','cancelling'].includes(run.status)&&<button className="button danger small" disabled={!!busy||run.status==='cancelling'} onClick={()=>void action('cancel')}><Icon name="stop" size={14}/>{run.status==='cancelling'?t('停止中','Stopping'):t('停止執行','Stop run')}</button>}{run.status==='cancelling'&&run.workers_pending_cleanup&&<button className="button secondary small" disabled={!!busy} onClick={()=>void action('reconcile')}><Icon name="check" size={14}/>{t('確認已清理','Confirm cleanup')}</button>}{['cancelled','incomplete','failed','blocked'].includes(run.status)&&(resumable(run)?<button className="button secondary small" disabled={!!busy} onClick={()=>void action('resume')}><Icon name="refresh" size={14}/>{t('嘗試恢復','Try to resume')}</button>:<span className="resume-note" title={t('有未確認的副作用、清理、用量或部署變更；請重設環境後建立新的執行','There are unconfirmed side effects, cleanup, usage or deployment changes; reset the environment and create a new run')}>{t('需建立新的執行','Needs a new run')}</span>)}<ReportMenu run={run}/></div></div>
    <section className="stage-panel" aria-label={t('評估階段','Assessment stages')}><div className="stage-top"><span className="eyebrow">ASSESSMENT PIPELINE</span><span>{Math.max(0,stageIndex)+1} / {STAGES().length} {t('階段','stages')}</span></div><ol className="stage-list">{STAGES().map(([id,label],i)=>{const done=i<stageIndex||(run.status==='completed'&&i===stageIndex);return <li key={id} className={`${done?'done':''} ${i===stageIndex?'current':''}`} aria-current={i===stageIndex?'step':undefined}><span className="stage-circle">{done?<Icon name="check" size={14}/>:String(i+1).padStart(2,'0')}</span><span>{label}</span></li>;})}</ol></section>
    <div className="metrics-grid"><Metric title={t('安全發現','Security findings')} value={findings.length} note={t(`${dynamic} 項具動態驗證`,`${dynamic} dynamically verified`)} icon="shield"/><Metric title={t('威脅情境','Threat scenarios')} value={threats.length} note={t(`${run.threat_model?.assets?.length??0} 項資產`,`${run.threat_model?.assets?.length??0} assets`)} icon="link"/><Metric title={t('測試案例','Test cases')} value={run.cases?.length??0} note={t(`${run.executions?.length??0} 筆執行紀錄`,`${run.executions?.length??0} execution records`)} icon="code"/><Metric title={t('驗證缺口','Verification gaps')} value={run.gaps?.length??0} note={t('未驗證項目明確保留','Unverified items are kept explicitly')} icon="alert" warn={!!run.gaps?.length}/></div>
    <div className="tabs" role="tablist" aria-label={t('評估內容','Assessment content')}>{[['overview',t('總覽與模型','Overview and models')],['trace',t('威脅與測試','Threats and tests')],['findings',t(`發現 (${findings.length})`,`Findings (${findings.length})`)],['evidence',t('執行與證據','Executions and evidence')],['activity',t('執行紀錄','Activity log')]].map(([id,label])=><button id={`tab-${id}`} role="tab" aria-selected={tab===id} aria-controls="tab-panel" key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}</div>
    <div id="tab-panel" role="tabpanel" aria-labelledby={`tab-${tab}`}>
      {tab==='overview'&&<div className="detail-columns"><div><Panel title={t('獨立審查小組','Independent review panel')} eyebrow="MODEL ATTRIBUTION"><div className="agent-list">{run.manifest.models.map((model,i)=>{const review=run.reviews?.find(r=>r.agent_id===model.id);return <div className="agent-row" key={model.id}><span className={`agent-avatar a${i}`}><Icon name={i===0?'shield':'chip'} size={21}/></span><div className="agent-info"><strong>{ROLE_LABELS[model.role]}<code>{model.id}</code></strong><span>{model.provider==='demo'?t('合成示範','Synthetic demo'):PROVIDERS[model.provider]} · {model.model_id||t('未設定','Not set')}</span><small>{t('模型家族','Model family')} {model.family||t('未設定','Not set')}{review?.input_hash?t(` · 輸入 ${short(review.input_hash)}`,` · input ${short(review.input_hash)}`):''}</small></div><div className="agent-result">{review?<><Badge value={review.status}/><small>{review.findings.length} {t('項候選','candidates')}{review.simulated?t(' · 合成',' · synthetic'):''}</small></>:<span className="muted">{model.role==='commander'?t('協調流程','Coordinates the flow'):t('尚無審查結果','No review result yet')}</span>}</div></div>;})}</div><div className="panel-footnote">{t('初審先封存，再進行證據仲裁。模型同意的數量不等於漏洞成立。','Initial reviews are sealed before evidence adjudication. How many models agree does not establish a vulnerability.')}</div></Panel><Panel title={t('評估範圍','Assessment scope')} eyebrow="IMMUTABLE CONTEXT"><dl className="context-list"><dt>{t('來源','Source')}</dt><dd>{run.manifest.source_path||t('本地合成 fixture','Local synthetic fixture')}</dd><dt>{t('目標','Target')}</dt><dd>{run.manifest.target_url||t('示範不對外連線','The demo makes no outbound connections')}</dd><dt>{t('來源摘要','Source digest')}</dt><dd><code>{run.threat_model?.source_digest||t('尚未建立','Not created yet')}</code></dd><dt>{t('威脅模型摘要','Threat model digest')}</dt><dd><code>{run.threat_model?.hash||t('尚未建立','Not created yet')}</code></dd><dt>{t('資料政策','Data policy')}</dt><dd>{run.manifest.data_policy==='local_only'?t('僅本地模型','Local models only'):t('允許指定雲端模型','Named cloud models allowed')}</dd><dt>{t('備註','Notes')}</dt><dd>{run.manifest.notes||'—'}</dd></dl></Panel></div><div><Panel title={t('資源使用量','Resource usage')} eyebrow="RUN BUDGET"><Usage label={t('目標請求','Target requests')} used={run.usage?.requests} max={run.manifest.budget.max_requests}/><Usage label={t('模型呼叫','Model calls')} used={run.usage?.model_calls} max={run.manifest.budget.max_model_calls}/><Usage label="Tokens" used={run.usage?.tokens} max={run.manifest.budget.max_tokens}/><div className="budget-time"><Icon name="pulse" size={15}/>{t('時間上限','Time limit')} {formatNumber(run.manifest.budget.max_seconds)} {t('秒','s')}</div></Panel><Panel title={t('驗證缺口','Verification gaps')} eyebrow="KNOWN UNKNOWNS">{run.gaps?.length?<div className="gaps-list">{run.gaps.map((gap,i)=><div className="gap" key={i}><Icon name="alert" size={16}/><SafeText value={gap}/></div>)}</div>:<p className="panel-copy">{t('目前沒有已記錄的缺口。這不代表評估已完成，也不表示系統沒有風險。','No gaps recorded yet. This does not mean the assessment is complete, nor that the system has no risk.')}</p>}</Panel>{run.limitations?.length?<Panel title={t('能力限制','Capability limits')}><SafeText value={run.limitations}/></Panel>:null}{run.error!=null&&<Panel title={t('執行問題','Execution problems')}><SafeText value={typeof run.error==='string'&&run.error_zh?t(run.error_zh,run.error):run.error}/></Panel>}</div></div>}
      {tab==='trace'&&<><div className="section-intro"><Icon name="link"/><div><h2>{t('從安全條件，追到實際觀測','From security conditions to actual observations')}</h2><p>{t('每項威脅對應案例與結果；尚未執行或缺少必要觀測時，保留未確認狀態。','Each threat maps to its cases and results; anything not yet run or missing a required observation stays unconfirmed.')}</p></div></div>{threats.length?threats.map(threat=><article className="threat-card" key={threat.id}><div className="threat-header"><div className="trace-id">{threat.id}</div><div><h3>{threat.title}</h3><span className="muted">{threat.category} · {threat.requirement_id}</span></div><Badge value={threat.testability==='blocked'?'blocked':'info'}>{threat.testability==='blocked'?t('尚不可自動驗證','Not automatically verifiable yet'):t('可自動驗證','Automatically verifiable')}</Badge></div><div className="invariant"><span>{t('應維持的安全條件','Security condition that must hold')}</span><p>{threat.invariant}</p></div>{threat.blocked_reason&&<p className="inline-warning">{threat.blocked_reason}</p>}<div className="trace-cases">{run.cases.filter(c=>c.threat_ids.includes(threat.id)).map(c=><CaseCard key={c.id} testCase={c} executions={run.executions.filter(e=>e.case_id===c.id)}/>)}{!run.cases.some(c=>c.threat_ids.includes(threat.id))&&<div className="trace-empty">{t('尚無對應案例','No matching case yet')}</div>}</div><details className="text-details"><summary>{t('檢視資產、假設與控制證據','View assets, assumptions and control evidence')}</summary><SafeText value={{asset_ids:threat.asset_ids,preconditions:threat.preconditions,assumptions:threat.assumptions,control_evidence:threat.control_evidence,impact:threat.impact}}/></details></article>):<Empty title={t('威脅模型尚未建立','No threat model yet')}>{t('完成白箱審查與仲裁後，系統才會建立威脅模型並設計測試。','The threat model and tests are designed only after white-box review and adjudication finish.')}</Empty>}{run.cases.filter(c=>!c.threat_ids.some(id=>threats.some(t=>t.id===id))).map(c=><CaseCard key={c.id} testCase={c} executions={run.executions.filter(e=>e.case_id===c.id)}/>)}</>}
      {tab==='trace'&&<TraceRegister run={run}/>}
      {tab==='findings'&&<Findings run={run} onEvidence={id=>{setFocusEvidence(id);setTab('evidence');}} onUpdated={onCreated}/>}
      {tab==='evidence'&&<><div className="notice subtle"><Icon name="lock"/><p>{t('證據以純文字顯示，不執行目標回傳的 HTML 或腳本。Trace 是額外觀測，不等同已發生的外部工具副作用。','Evidence is shown as plain text; HTML or scripts returned by the target never run. A trace is an extra observation, not proof that an external tool side effect happened.')}</p></div>{run.executions?.length?run.executions.map((ex,i)=>{const result=executionResult(ex);return <article className="execution-card" key={String(ex.id??i)}><div className="execution-header"><div><span className="eyebrow">EXECUTION {String(i+1).padStart(2,'0')}</span><h3>{String(ex.case_id??ex.id??t('未記錄案例識別','Case ID not recorded'))}</h3></div><Badge value={String(result.status??'inconclusive')}/></div><p>{String(result.reason??t('未提供判定說明','No verdict explanation provided'))}</p><div className="execution-meta"><span>{result.requests==null?t('請求次數未知（結果不明，未確認是否已送達）','Request count unknown (outcome unknown; delivery not confirmed)'):t(`${formatNumber(Number(result.requests))} 次請求`,`${formatNumber(Number(result.requests))} requests`)}</span><span>{String(ex.observation_mode??run.cases.find(c=>c.id===ex.case_id)?.observation_mode??t('未記錄觀測模式','Observation mode not recorded'))}</span></div><details className="text-details"><summary>{t('觀測紀錄','Observations')}</summary><SafeText value={result.observations??[]}/></details><details className="text-details"><summary>{t('原始證據與關聯識別','Raw evidence and linked IDs')}</summary><SafeText value={ex}/></details></article>;}):<Empty title={t('尚無動態執行證據','No dynamic execution evidence yet')}>{t('威脅模型與測試案例通過閘門後，才會對設定的目標進行驗證。','The configured target is tested only after the threat model and test cases pass their gates.')}</Empty>}</>}
      {tab==='evidence'&&<EvidenceBrowser key={run.id} run={run} focusId={focusEvidence}/>}
      {tab==='activity'&&<Panel title={t('完整執行紀錄','Full activity log')} eyebrow="AUDIT TRAIL" action={<span className="muted">{events.length} {t('筆事件','events')}</span>}>{events.length?<ol className="event-list">{events.map((e,i)=><li key={`${e.seq}-${i}`} className={e.level}><time>{date(e.at)}</time><span className="event-dot"/><div><div className="event-label"><strong>{STAGES().find(([id])=>id===e.stage)?.[1]??e.stage}</strong>{e.agent_id&&<code>{e.agent_id}</code>}<small>#{e.seq}</small></div><p>{e.message}</p></div></li>)}</ol>:<Empty title={t('等待第一筆事件','Waiting for the first event')}>{t('啟動評估後，進度會自動更新。','Progress updates automatically once the assessment starts.')}</Empty>}</Panel>}
    </div>
  </>;
}
function Metric({title,value,note,icon,warn=false}: {title:string;value:number;note:string;icon:string;warn?:boolean}) {return <div className={`metric ${warn?'warn':''}`}><div><span>{title}</span><Icon name={icon} size={18}/></div><strong>{formatNumber(value)}</strong><small>{note}</small></div>;}
function Usage({label,used=0,max}: {label:string;used?:number;max:number}) {const percentage=Math.min(100,max>0?used/max*100:0);return <div className="usage"><div><span>{label}</span><strong>{formatNumber(used)}<small> / {formatNumber(max)}</small></strong></div><div className="usage-track" role="progressbar" aria-label={label} aria-valuenow={used} aria-valuemin={0} aria-valuemax={Math.max(max,used)}><span style={{width:`${percentage}%`}}/></div></div>;}
function CaseCard({testCase:c,executions}: {testCase:TestCase;executions:Record<string,unknown>[]}) {return <div className="case-card"><div className="case-top"><span className="trace-connector"/><div><code>{c.id}</code><h4>{c.title}</h4></div><Badge value={executions.length?String(executionResult(executions[executions.length-1]).status??'inconclusive'):'created'}>{executions.length?undefined:t('尚未執行','Not run yet')}</Badge></div><div className="case-route"><span>{c.method}</span><code>{c.path}</code><small>{c.adapter}{c.designed_by==='model'?t(' · 模型設計',' · model-designed'):''}</small></div><div className="case-oracle"><strong>Oracle</strong><code>{c.oracle.kind}</code><span>{c.observation_mode==='instrumented_observation'?t('含內部觀測','Includes internal observation'):t('外部觀測','External observation')}</span><span>{c.repetitions} {t('次驗證','verifications')}</span></div><details className="text-details"><summary>{t('必要觀測與案例契約','Required observations and case contract')}</summary><SafeText value={{identity:c.identity,headers:c.headers,body:c.body,designed_by:c.designed_by??'operator',required_observations:c.oracle.required_observations,allowed_statuses:c.oracle.allowed_statuses,expected_role:c.oracle.expected_role,preconditions:c.preconditions,side_effects:c.side_effects,cleanup:c.cleanup,source_digest:c.source_digest,threat_model_hash:c.threat_model_hash,hash:c.hash}}/></details></div>;}
function Findings({run,onEvidence,onUpdated}: {run:Run;onEvidence:(id:string)=>void;onUpdated?:(run:Run)=>void}) {
  const findings=run.findings??[];
  const [filter,setFilter]=useState('all');const filtered=filter==='all'?findings:findings.filter(f=>f.state===filter);
  return <><div className="finding-toolbar"><p>{t('嚴重度與證據狀態分別記錄，尚待驗證的假設不會顯示為已證實。','Severity and evidence state are recorded separately; an unverified hypothesis is never shown as confirmed.')}</p><label className="sr-only" htmlFor="finding-filter">{t('篩選證據狀態','Filter by evidence state')}</label><select id="finding-filter" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">{t('全部證據狀態','All evidence states')}</option>{Object.entries(STATES).map(([key,label])=><option value={key} key={key}>{label}</option>)}</select></div>{filtered.length?filtered.map(f=><article className="finding-card" key={f.id}><div className="finding-header"><span className={`severity ${f.severity}`}>{SEVERITY[f.severity]??f.severity}</span><code>{f.id}</code><Badge value={f.state}>{STATES[f.state]??f.state}</Badge></div><h3>{f.title}</h3><p>{f.description}</p>{f.file&&<div className="finding-location"><Icon name="code" size={15}/><code>{f.file}{f.line?`:${f.line}`:''}</code>{f.cwe&&<span>{f.cwe}</span>}</div>}<div className="finding-links"><div><span>{t('提出者','Raised by')}</span>{f.agent_ids?.length?f.agent_ids.map(id=><code key={id}>{id}</code>):t('未記錄','Not recorded')}</div><div><span>{t('威脅','Threats')}</span>{f.threat_ids?.length?f.threat_ids.map(id=><code key={id}>{id}</code>):t('未關聯','Not linked')}</div><div><span>{t('證據','Evidence')}</span>{f.evidence_ids?.length?f.evidence_ids.map(id=><button type="button" className="evidence-link" key={id} onClick={()=>onEvidence(id)}>{short(id)}<Icon name="arrow" size={10}/></button>):t('待補足','Still needed')}</div></div><DecisionControl run={run} finding={f} onUpdated={onUpdated}/></article>):<Empty title={findings.length?t('沒有符合篩選的發現','No findings match the filter'):t('目前沒有安全發現','No security findings yet')}>{t('請同時查看執行狀態、涵蓋範圍與驗證缺口；空白清單不等於安全保證。','Check the execution status, coverage and verification gaps too; an empty list is not a security guarantee.')}</Empty>}</>;
}

// Mirrors the backend decision rules: only a black-box execution of this run can
// count as counterevidence, a refutation needs a pass, and an observed violation
// is never decided away - it needs a linked retest.
function DecisionControl({run,finding,onUpdated}: {run:Run;finding:Finding;onUpdated?:(run:Run)=>void}) {
  const [decision,setDecision]=useState<'refuted'|'inconclusive'>('inconclusive');
  const [rationale,setRationale]=useState('');
  const [evidenceIds,setEvidenceIds]=useState<string[]>([]);
  const [threatIds,setThreatIds]=useState<string[]>([]);
  const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  const applicable=finding.threat_ids.length?finding.threat_ids:threatIds;
  const executions=new Map((run.executions??[]).map(e=>[String(record(e).evidence_id??''),e]));
  const caseThreats=(evidenceId:string)=>new Set(run.cases.find(c=>c.id===String(record(executions.get(evidenceId)??{}).case_id??''))?.threat_ids??[]);
  const countsThreat=(evidenceId:string,threats:string[])=>threats.length?[...threats].some(t=>caseThreats(evidenceId).has(t)):false;
  const candidates=run.artifacts.map(record).filter(a=>a.producer==='blackbox-worker'&&!finding.evidence_ids.includes(String(a.id)));
  const needThreats=!finding.threat_ids.length;
  if(finding.state==='validated_dynamic')return <p className="field-hint">{t('已觀測到違規的發現不能在此排除；請建立修補複測驗證修正。','A finding with an observed violation cannot be refuted here; create a remediation retest to verify the fix.')}</p>;
  if(['running','cancelling'].includes(run.status)||!candidates.length&&!finding.decisions?.length)return null;
  async function decide(){setBusy(true);setError('');try{const next=await api<Run>(`/runs/${encodeURIComponent(run.id)}/findings/${encodeURIComponent(finding.id)}/decision`,{decision,rationale:rationale.trim(),evidence_ids:evidenceIds,threat_ids:finding.threat_ids.length?[]:threatIds});onUpdated?.(next);setRationale('');setEvidenceIds([]);setThreatIds([]);}catch(e){setError(e instanceof Error?e.message:String(e));}finally{setBusy(false);}}
  // Mirror the backend's refutation rules client-side: a refutation needs a cited
  // pass, and no execution testing these threats may have observed a violation.
  const observedFail=(run.executions??[]).some(e=>String(executionResult(e).status??'')==='fail'&&applicable.some(t=>caseThreats(String(record(e).evidence_id??'')).has(t)));
  const citedPass=evidenceIds.some(id=>String(executionResult(executions.get(id)??{}).status??'')==='pass');
  const refutedBlocked=decision==='refuted'&&(observedFail||!citedPass);
  const blocked=!rationale.trim()||!evidenceIds.length||(needThreats&&!threatIds.length)||refutedBlocked;
  return <details className="text-details finding-decision">
    <summary>{t('證據裁決','Evidence decision')}{finding.decisions?.length?t(` · 已記錄 ${finding.decisions.length} 項`,` · ${finding.decisions.length} recorded`):''}</summary>
    <p className="field-hint">{t('只有本次執行中、與此發現威脅相關的黑箱執行紀錄可以當作反證；模型審查與掃描輸出只是來源，不能推翻自己。','Only black-box executions in this run that test this finding\'s threats can count as counterevidence; model reviews and scanner output are its sources and cannot overturn it.')}</p>
    {finding.decisions?.map((entry,i)=><p className="field-hint" key={i}>#{i+1} {entry.actor} {t('於','on')} {date(entry.at)} {t('裁決為「','decided “')}{STATES[entry.decision]??entry.decision}{t('」（原狀態：','” (previously: ')}{STATES[entry.previous_state]??entry.previous_state}{t('）；理由：','); reason: ')}{entry.rationale.slice(0,200)}{entry.rationale.length>200?'…':''}</p>)}
    <div className="form-grid"><Field label={t('裁決','Decision')}><select value={decision} onChange={e=>setDecision(e.target.value as 'refuted'|'inconclusive')}><option value="inconclusive">{t('尚無定論（證據不足）','Inconclusive (insufficient evidence)')}</option><option value="refuted">{t('已排除（反證執行觀測到安全條件成立）','Refuted (a counterevidence execution observed the security condition holding)')}</option></select></Field></div>
    <Field label={t('裁決理由（會存入證據紀錄）','Rationale (stored in the evidence record)')}><textarea value={rationale} onChange={e=>setRationale(e.target.value)} rows={2} maxLength={4000} placeholder={t('說明為什麼這些執行紀錄足以支持此裁決。','Explain why these execution records are enough to support this decision.')}/></Field>
    {needThreats&&<fieldset className="retest-findings"><legend>{t('此反證所測試的威脅（此發現尚未關聯威脅）','Threats tested by this counterevidence (this finding has no linked threats)')}</legend>{(run.threat_model?.threats??[]).map(t=><label key={t.id}><input type="checkbox" checked={threatIds.includes(t.id)} onChange={e=>{const next=e.target.checked?[...threatIds,t.id]:threatIds.filter(id=>id!==t.id);setThreatIds(next);setEvidenceIds(prev=>prev.filter(id=>countsThreat(id,next)));}}/><span>{t.title}<small>{t.id}</small></span></label>)}{!run.threat_model?.threats?.length&&<p className="field-hint">{t('此執行沒有威脅模型可選擇。','This run has no threat model to choose from.')}</p>}</fieldset>}
    <fieldset className="retest-findings"><legend>{t('引用的黑箱執行證據','Cited black-box execution evidence')}</legend>{candidates.map(artifact=>{const id=String(artifact.id);const ex=executions.get(id);const status=String(executionResult(ex??{}).status??'inconclusive');const usable=countsThreat(id,applicable);return <label key={id} className={usable?'':'muted'}><input type="checkbox" checked={evidenceIds.includes(id)} disabled={!usable} onChange={e=>setEvidenceIds(e.target.checked?[...evidenceIds,id]:evidenceIds.filter(v=>v!==id))}/><span>{String(record(ex??{}).case_id??t('未記錄案例','Case not recorded'))}<small>{short(id)} · {STATUS[status]??status}</small></span></label>;})}{!candidates.length&&<p className="field-hint">{t('此執行沒有可引用的黑箱執行證據。','This run has no black-box execution evidence to cite.')}</p>}{needThreats&&!threatIds.length&&<p className="field-hint">{t('先選擇反證所測試的威脅，才會開放可用的執行證據。','Choose the threats the counterevidence tests first; the available execution evidence then becomes selectable.')}</p>}</fieldset>
    {decision==='refuted'&&observedFail&&<p className="field-hint">{t('此執行已有測試這些威脅的案例觀測到違規，後端不會接受「已排除」；請改為「尚無定論」或以修補複測驗證。','A case in this run that tests these threats already observed a violation, so the backend will not accept Refuted; choose Inconclusive or verify with a remediation retest.')}</p>}
    {decision==='refuted'&&!observedFail&&!citedPass&&<p className="field-hint">{t('「已排除」需要至少一筆被引用執行觀測到安全條件成立（pass）。','Refuted needs at least one cited execution that observed the security condition holding (pass).')}</p>}
    {error&&<p className="inline-warning" role="alert">{error}</p>}
    <button type="button" className="button secondary small" disabled={busy||blocked} onClick={()=>void decide()}>{busy?t('記錄中…','Recording…'):t('記錄證據裁決','Record evidence decision')}</button>
  </details>;
}

function EvidenceBrowser({run,focusId}: {run:Run;focusId:string}) {
  const [data,setData]=useState<Record<string,unknown>>({});
  const [loading,setLoading]=useState('');const [error,setError]=useState('');
  const artifacts=run.artifacts.map(record);
  const load=useCallback(async(id:string)=>{setLoading(id);setError('');try{const result=await api<unknown>(`/runs/${encodeURIComponent(run.id)}/evidence/${encodeURIComponent(id)}`);setData(prev=>({...prev,[id]:result}));}catch(e){setError(e instanceof Error?e.message:String(e));}finally{setLoading('');}},[run.id]);
  useEffect(()=>{if(focusId&&artifacts.some(a=>a.id===focusId)){void load(focusId);window.setTimeout(()=>document.getElementById(`artifact-${focusId}`)?.scrollIntoView({behavior:'smooth',block:'center'}),80);}},[focusId,load]);
  if(!artifacts.length)return null;
  return <Panel title={t('可驗證的證據檔案','Verifiable evidence files')} eyebrow="EVIDENCE REGISTER"><p className="panel-copy evidence-intro">{t('開啟時由後端核對內容摘要；證據 ID 可連回發現與執行紀錄。','On opening, the backend checks the content digest; evidence IDs link back to findings and execution records.')}</p>{error&&<div className="inline-warning" role="alert">{error}</div>}<div className="artifact-list">{artifacts.map(artifact=>{const id=String(artifact.id);return <div className={`artifact ${id===focusId?'highlight':''}`} id={`artifact-${id}`} key={id}><div className="artifact-top"><Icon name="file" size={18}/><div><strong>{String(artifact.producer??t('證據','Evidence'))}</strong><code>{id}</code></div><button type="button" className="button secondary small" disabled={!!loading} onClick={()=>void load(id)}>{loading===id?t('核對中…','Checking…'):id in data?t('重新核對','Check again'):t('檢視證據','View evidence')}</button></div><div className="artifact-hash"><span>SHA-256</span><code>{String(artifact.sha256??t('未記錄','Not recorded'))}</code></div>{id in data&&<SafeText value={data[id]}/>}</div>;})}</div></Panel>;
}

function AuthProfilesEditor({profiles,onChange}: {profiles:AuthProfile[];onChange:(profiles:AuthProfile[])=>void}) {
  function update(index:number,patch:Partial<AuthProfile>) {onChange(profiles.map((p,i)=>i===index?{...p,...patch}:p));}
  return <details className="text-details" style={{marginTop:0,marginBottom:23}}><summary>{t('測試身分與憑證（可選）','Test identities and credentials (optional)')}</summary><p className="field-hint">{t('用獨立測試帳號驗證權限邊界。僅填憑證環境變數名稱；角色宣告本身不等於角色已獲驗證。憑證須在啟動控制台的環境以 VIBEAUDIT_TARGET_CREDENTIAL_ORIGINS（名稱=origin）綁定到目標 origin，未綁定時預檢會拒絕。','Use separate test accounts to verify permission boundaries. Enter only the credential\'s environment variable name; a declared role is not a verified role. Bind each credential to the target origin with VIBEAUDIT_TARGET_CREDENTIAL_ORIGINS (name=origin) in the environment that starts the console; preflight refuses an unbound one.')}</p>{profiles.map((profile,index)=><div className="auth-profile" key={index}><div className="auth-profile-top"><strong>{t('測試身分','Test identity')} {index+1}</strong><button type="button" className="icon-button" aria-label={t(`移除測試身分 ${index+1}`,`Remove test identity ${index+1}`)} onClick={()=>onChange(profiles.filter((_,i)=>i!==index))}><Icon name="close" size={15}/></button></div><div className="form-grid"><Field label={t('身分識別','Identity ID')}><input value={profile.id} onChange={e=>update(index,{id:e.target.value})} placeholder="tenant-a-user"/></Field><Field label={t('預期角色','Expected role')}><input value={profile.role} onChange={e=>update(index,{role:e.target.value})} placeholder="user"/></Field><Field label={t('憑證的環境變數名稱','Credential environment variable name')}><input value={profile.credential_env} onChange={e=>update(index,{credential_env:e.target.value})} placeholder="VIBEAUDIT_USER_A_TOKEN" autoComplete="off"/></Field><Field label={t('HTTP Header 名稱','HTTP header name')}><input value={profile.header} onChange={e=>update(index,{header:e.target.value})} placeholder="Authorization"/></Field><Field label={t('憑證前綴','Credential prefix')}><input value={profile.scheme} onChange={e=>update(index,{scheme:e.target.value})} placeholder={t('Bearer；不需前綴時可留白','Bearer; leave blank for no prefix')}/></Field></div><div className="check-options"><label><input type="checkbox" checked={profile.model_selectable===true} onChange={e=>update(index,{model_selectable:e.target.checked})}/>{t('允許模型設計的案例使用此身分','Allow model-designed cases to use this identity')}</label></div><p className="field-hint">{t('預設不允許；高權限帳號請勿勾選。操作者自填的案例不受此限。','Off by default; do not check this for privileged accounts. Operator-written cases are not limited by it.')}</p></div>)}<button type="button" className="button secondary small" style={{marginTop:12}} onClick={()=>onChange([...profiles,{id:`identity-${profiles.length+1}`,role:'user',credential_env:'',header:'Authorization',scheme:'Bearer'}])}><Icon name="plus" size={14}/>{t('新增測試身分','Add test identity')}</button></details>;
}

const demoModels=():ModelProfile[]=>['commander','reviewer-a','reviewer-b','reviewer-c'].map((id,i)=>({id,role:i===0?'commander':'reviewer',provider:'demo',model_id:`synthetic-${i===0?'commander':i}`,family:`synthetic-${i}`,endpoint:'',credential_env:'',temperature:0,max_output_tokens:3000}));
const defaultBudget:Budget={max_seconds:600,max_requests:30,max_model_calls:20,max_tokens:50000};
type AllowedRequest=RunInput['allowed_requests'][number];
// One allowed request per line: METHOD /path, then optional model-body, then an optional JSON object of the header
// values a model-designed case may use on this endpoint, e.g. GET /api {"Accept":["application/json","text/html"]}.
// JSON because a value such as "application/json; charset=utf-8" contains a space. The server checks the values.
// The path cannot hold '{', so header JSON written without a space before it is refused, not read as part of the path.
const REQUEST_LINE=/^(GET|POST|PUT|PATCH|DELETE|HEAD|OPTIONS)\s+(\/[^\s{]*)(\s+model-body)?(?:\s+(\{.*\}))?$/;
function parseRequestLine(line:string):AllowedRequest|null{
  const m=REQUEST_LINE.exec(line.trim());if(!m)return null;
  let headers:Record<string,string[]>|undefined;
  if(m[4]){try{const v:unknown=JSON.parse(m[4]);if(!v||typeof v!=='object'||Array.isArray(v)||!Object.values(v as object).every(x=>Array.isArray(x)&&x.length>0&&x.every(y=>typeof y==='string')))return null;headers=v as Record<string,string[]>;}catch{return null;}}
  return {method:m[1] as AllowedRequest['method'],path:m[2],...(m[3]?{model_body:true}:{}),...(headers?{model_headers:headers}:{})};
}
const requestLine=(r:AllowedRequest)=>r.method+' '+r.path+(r.model_body?' model-body':'')+(r.model_headers&&Object.keys(r.model_headers).length?' '+JSON.stringify(r.model_headers):'');
function CreateForm({onCreate,busy,connected}: {onCreate:(input:RunInput)=>Promise<void>;busy:boolean;connected:boolean}) {
  const lang=useLang();
  const [mode,setMode]=useState<'demo'|'live'>('demo');const [name,setName]=useState(t('我的第一個安全評估','My first security assessment'));
  const [source,setSource]=useState('');const [target,setTarget]=useState('');const [deployment,setDeployment]=useState('');
  const [dataPolicy,setDataPolicy]=useState<'local_only'|'cloud_allowed'>('local_only');const [origins,setOrigins]=useState('');const [ips,setIps]=useState('');const [requests,setRequests]=useState('');const [notes,setNotes]=useState('');const [caseText,setCaseText]=useState('');
  const [budget,setBudget]=useState<Budget>(defaultBudget);const [models,setModels]=useState<ModelProfile[]>(demoModels);
  const [authProfiles,setAuthProfiles]=useState<AuthProfile[]>([]);
  const [extensions,setExtensions]=useState<RunExtensions>(defaultExtensions);
  const [specialRole,setSpecialRole]=useState<ModelProfile['role']>('architecture_mapper');
  const [formError,setFormError]=useState('');const [probe,setProbe]=useState<Record<string,{pending:boolean;message:string;ok?:boolean}>>({});
  const split=(v:string)=>v.split(/[\s,]+/).map(s=>s.trim()).filter(Boolean);
  const validation=useMemo(()=>{
    const errors:string[]=[];if(!name.trim())errors.push(t('請填寫評估名稱。','Enter an assessment name.'));
    if(Object.values(budget).some(v=>!Number.isFinite(v)||v<1||!Number.isInteger(v)))errors.push(t('預算須為大於 0 的整數。','Budgets must be whole numbers greater than 0.'));
    if(budget.max_seconds<10||budget.max_seconds>14400)errors.push(t('時間上限須介於 10 與 14,400 秒。','The time limit must be between 10 and 14,400 seconds.'));
    if(budget.max_requests>10000||budget.max_model_calls>500)errors.push(t('請求上限不可超過 10,000 次，模型呼叫上限不可超過 500 次。','The request limit cannot exceed 10,000 and the model call limit cannot exceed 500.'));
    if(budget.max_tokens<1000||budget.max_tokens>2000000)errors.push(t('Token 預算須介於 1,000 與 2,000,000。','The token budget must be between 1,000 and 2,000,000.'));
    if(mode==='live'){
      if(!/^(?:[A-Za-z]:[\\/]|\/)/.test(source.trim()))errors.push(t('來源程式請使用本機絕對路徑。','Use an absolute local path for the source code.'));
      try{const u=new URL(target);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.hash)throw new Error();}catch{errors.push(t('請設定有效的 HTTP(S) staging URL，不含帳密或 fragment。','Set a valid HTTP(S) staging URL without credentials or a fragment.'));}
      if(!deployment.trim())errors.push(t('請填寫部署識別，以對應本次測試版本。','Enter a deployment ID that identifies the version under test.'));
      if(!split(ips).length)errors.push(t('請明確列出允許測試的目標 IP。','List the target IPs allowed for testing explicitly.'));
      if(requests.split('\n').filter(s=>s.trim()).some(s=>parseRequestLine(s)===null))errors.push(t('允許的請求每行填寫 GET /path 或 POST /path，方法與路徑須精確；可接收模型撰寫本文的端點加 model-body；模型設計的案例可用的 header 值寫在行末的 JSON，例如 {"Accept":["application/json"]}。','Write one allowed request per line as GET /path or POST /path, with the exact method and path; add model-body for an endpoint that may receive a model-written body; put the header values a model-designed case may use in JSON at the end of the line, for example {"Accept":["application/json"]}.'));
      if(models.some(m=>!m.model_id.trim()||!m.family.trim()||!m.endpoint.trim()))errors.push(t('所有 Agent 都需要模型 ID、家族和 API 端點。','Every agent needs a model ID, family and API endpoint.'));
      if(models.some(m=>m.provider==='demo'))errors.push(t('實際評估不能使用合成模型。','A live assessment cannot use synthetic models.'));
      if(models.some(m=>{try{const u=new URL(m.endpoint);return !['http:','https:'].includes(u.protocol)||!!u.username||!!u.password;}catch{return true;}}))errors.push(t('模型端點必須為有效的 HTTP(S) URL，不能內含金鑰。','Model endpoints must be valid HTTP(S) URLs with no key inside.'));
      if(dataPolicy==='cloud_allowed'&&!split(origins).length)errors.push(t('允許雲端時，請明確填寫模型 origin allowlist。','When cloud models are allowed, fill in the model origin allowlist explicitly.'));
      if(models.some(m=>m.credential_env&&!/^VIBEAUDIT_[A-Z0-9_]+$/.test(m.credential_env)))errors.push(t('憑證欄位須填 VIBEAUDIT_* 格式的環境變數名稱，不能填 API 金鑰。','Credential fields take a VIBEAUDIT_* environment variable name, not an API key.'));
      if(new Set(models.filter(m=>m.role==='reviewer').map(m=>m.family.trim().toLowerCase())).size!==3)errors.push(t('三位審查員需要三個不同的模型家族。','The three reviewers need three different model families.'));
      if(new Set(models.filter(m=>m.role==='reviewer').map(m=>[m.provider,m.model_id,m.endpoint].join('|'))).size!==3)errors.push(t('三位審查員需要三種不同的模型配置。','The three reviewers need three different model configurations.'));
      if(models.some(m=>!Number.isInteger(m.max_output_tokens)||m.max_output_tokens<256||m.max_output_tokens>16000))errors.push(t('單次模型輸出須介於 256 與 16,000 tokens。','Output per model call must be between 256 and 16,000 tokens.'));if(models.some(m=>m.temperature!==null&&(!Number.isFinite(m.temperature)||m.temperature<0||m.temperature>2)))errors.push(t('Temperature 須介於 0 與 2，或留空使用模型預設值。','Temperature must be between 0 and 2, or blank for the model default.'));
      if(authProfiles.some(p=>!p.id.trim()||!p.role.trim()||!/^VIBEAUDIT_[A-Z0-9_]+$/.test(p.credential_env)))errors.push(t('測試身分需要識別、角色與 VIBEAUDIT_* 憑證環境變數名稱。','Test identities need an ID, a role and a VIBEAUDIT_* credential environment variable name.'));
      if(new Set(authProfiles.map(p=>p.id)).size!==authProfiles.length)errors.push(t('測試身分的識別不能重複。','Test identity IDs cannot repeat.'));
      if(caseText.trim()){try{if(!Array.isArray(JSON.parse(caseText)))throw new Error();}catch{errors.push(t('自訂案例必須是 JSON 陣列。','Custom cases must be a JSON array.'));}}
    }return errors;
  },[name,budget,mode,source,target,deployment,ips,requests,models,dataPolicy,origins,caseText,authProfiles,lang]);
  function changeMode(next:'demo'|'live'){setMode(next);setProbe({});setModels(next==='demo'?demoModels():demoModels().map(m=>({...m,provider:'openai_compatible',model_id:'',family:'',endpoint:'http://127.0.0.1:11434/v1'})));}
  function updateModel(i:number,patch:Partial<ModelProfile>){setModels(prev=>prev.map((m,index)=>index===i?{...m,...patch}:m));setProbe(prev=>({...prev,[models[i].id]:{pending:false,message:''}}));}
  function changeProvider(i:number,provider:Provider){const defaults:Partial<Record<Provider,Partial<ModelProfile>>>={openai:{endpoint:'https://api.openai.com/v1',credential_env:'VIBEAUDIT_OPENAI_API_KEY',family:'gpt'},anthropic:{endpoint:'https://api.anthropic.com',credential_env:'VIBEAUDIT_ANTHROPIC_API_KEY',family:'claude'},nvidia_nim:{endpoint:'http://127.0.0.1:8001/v1',credential_env:'',family:'nemotron'},openai_compatible:{endpoint:'http://127.0.0.1:11434/v1',credential_env:'',family:''}};updateModel(i,{provider,model_id:'',...defaults[provider]});}
  // The origins field is disabled under local_only; stale cloud entries must not narrow the loopback check.
  function modelOrigins(){return dataPolicy==='local_only'?[]:split(origins);}
  async function probeModel(model:ModelProfile){setProbe(prev=>({...prev,[model.id]:{pending:true,message:t('檢查端點與能力…','Checking endpoint and capabilities…')}}));try{const result=await api<Record<string,unknown>>('/models/probe',{profile:model,data_policy:dataPolicy,allowed_model_origins:modelOrigins(),budget});const ok=result.available===false||result.ok===false||result.status==='failed'?false:true;setProbe(prev=>({...prev,[model.id]:{pending:false,ok,message:stringify(result)}}));}catch(e){setProbe(prev=>({...prev,[model.id]:{pending:false,ok:false,message:e instanceof Error?e.message:String(e)}}));}}
  function configuration():RunInput {
    return {...extensions,schema_version:2,name:name.trim(),mode,source_path:mode==='demo'?'':source.trim(),deployment_id:mode==='demo'?'':deployment.trim(),target_url:mode==='demo'?'':target.trim(),data_policy:mode==='demo'?'local_only':dataPolicy,allowed_model_origins:mode==='demo'?[]:modelOrigins(),allowed_target_ips:mode==='demo'?[]:split(ips),allowed_requests:mode==='demo'?[]:requests.split('\n').filter(s=>s.trim()).map(s=>{const r=parseRequestLine(s);if(!r)throw new Error(t(`允許的請求格式不正確，請先修正：${s.trim()}`,`An allowed request line is invalid; fix it first: ${s.trim()}`));return r;}),budget,models,auth_profiles:mode==='demo'?[]:authProfiles,notes,parent_run_id:null,cases:mode==='live'&&caseText.trim()?JSON.parse(caseText) as TestCase[]:[]};
  }
  function loadConfiguration(input:RunInput) {
    setName(input.name);setMode(input.mode);setSource(input.source_path);setTarget(input.target_url);setDeployment(input.deployment_id);setDataPolicy(input.data_policy);setOrigins(input.allowed_model_origins.join('\n'));setIps(input.allowed_target_ips.join('\n'));setRequests(input.allowed_requests.map(requestLine).join('\n'));setBudget(input.budget);setModels(input.models.length?input.models:demoModels());setAuthProfiles(input.auth_profiles);setNotes(input.notes);setCaseText(input.cases.length?JSON.stringify(input.cases,null,2):'');setExtensions({...defaultExtensions(),requirements:input.requirements??[],runtime_profile:input.runtime_profile??'default',fixture_profile:input.fixture_profile??null,static_tools:input.static_tools??['semgrep','osv','gitleaks'],deployment_header:input.deployment_header??null});setProbe({});setFormError('');
  }
  async function submit(e:FormEvent){e.preventDefault();setFormError('');if(validation.length){setFormError(validation.join(' '));return;}try{await onCreate(configuration());}catch{/* Shared API notice retains the failure. */}}

  return <><div className="page-heading"><div><div className="eyebrow">NEW ASSESSMENT</div><h1>{t('建立一個有邊界的評估','Create a bounded assessment')}</h1><p>{t('設定目標、審查模型與執行預算。系統會依序檢查階段條件。','Set the target, review models and run budget. The system checks each stage\'s conditions in order.')}</p></div><span className="local-label"><Icon name="lock" size={16}/>{t('本地執行','Runs locally')}</span></div><form onSubmit={submit} className="create-form"><div className="create-main"><ProjectControls configuration={configuration} onLoad={loadConfiguration}/><Panel title={t('評估方式','Assessment type')} eyebrow="01 / WORKSPACE"><div className="mode-switch">{(['demo','live'] as const).map(value=><button type="button" key={value} className={mode===value?'mode-option selected':'mode-option'} onClick={()=>changeMode(value)}><span className="mode-option-top"><Icon name={value==='demo'?'chip':'shield'}/><span className="radio-dot"/></span><strong>{value==='demo'?t('合成示範','Synthetic demo'):t('實際評估','Live assessment')}</strong><p>{value==='demo'?t('不用金鑰。在本地 fixture 上走完驗證流程。','No keys needed. Runs the verification flow on a local fixture.'):t('使用真實模型審查程式，測試你提供的 staging。','Reviews code with real models and tests the staging you provide.')}</p></button>)}</div><Field label={t('評估名稱','Assessment name')}><input value={name} onChange={e=>setName(e.target.value)} maxLength={140} placeholder={t('例如：客服 Agent 上線前評估','For example: pre-launch review of the support agent')} required/></Field>{mode==='demo'&&<div className="notice subtle compact"><Icon name="file" size={17}/><p>{t('示範會真正建立並啟動後端流程，但所有模型輸出與情境都是合成資料。','The demo really creates and starts the backend flow, but every model output and scenario is synthetic.')}</p></div>}</Panel>
      <Panel title={t('來源與測試範圍','Source and test scope')} eyebrow="02 / AUTHORIZED SCOPE"><fieldset disabled={mode==='demo'} className={mode==='demo'?'disabled-scope':''}><Field label={t('本機程式來源','Local source code')} hint={t('只讀取程式，不在主機上執行來源專案。','Code is only read; the source project never runs on this host.')}><input value={source} onChange={e=>setSource(e.target.value)} placeholder={t('C:\\projects\\my-app 或 /home/me/my-app','C:\\projects\\my-app or /home/me/my-app')}/></Field><div className="form-grid"><Field label={t('隔離 staging URL','Isolated staging URL')}><input value={target} onChange={e=>setTarget(e.target.value)} placeholder="http://127.0.0.1:8080"/></Field><Field label={t('部署識別','Deployment ID')} hint={t('例如 commit SHA 或部署版本。','For example a commit SHA or deployment version.')}><input value={deployment} onChange={e=>setDeployment(e.target.value)} placeholder="staging-2026-09-24"/></Field></div><Field label={t('允許的目標 IP','Allowed target IPs')} hint={t('逗號或換行分隔；重新導向不會自動放行。','Separate with commas or new lines; redirects are never allowed automatically.')}><textarea value={ips} onChange={e=>setIps(e.target.value)} rows={2} placeholder="127.0.0.1"/></Field><Field label={t('精確允許的請求','Exactly allowed requests')} hint={t('每行一組方法＋路徑。留白會阻擋全部黑箱請求；不代表允許全站。POST 只用於可重置的隔離環境。模型設計的案例只能把本文送到標 model-body 的端點；它可用的 header 值也只限行末 JSON 列出的值，沒列就不能帶 header。','One method + path per line. Leaving it blank blocks every black-box request; it never means the whole site is allowed. Use POST only on an isolated environment that can be reset. A model-designed case sends a body only to endpoints marked model-body, and uses only the header values listed in that line\'s trailing JSON; with no list it sends no header.')}><textarea value={requests} onChange={e=>setRequests(e.target.value)} rows={3} placeholder={'GET /api/profile {"Accept":["application/json"]}\nPOST /chat model-body'} spellCheck={false}/></Field></fieldset>{mode==='demo'&&<p className="field-hint">{t('示範模式不需要目標、路徑或部署設定。','Demo mode needs no target, paths or deployment settings.')}</p>}</Panel>
      <Panel title={t('指揮官與審查員','Commander and reviewers')} eyebrow="03 / INDEPENDENT REVIEW"><div className="model-intro"><p>{t('三位審查員各自處理相同核心問題，封存初審後再整合證據。不同模型不保證消除共同偏誤。','Each of the three reviewers handles the same core questions; initial reviews are sealed before the evidence is combined. Different models do not guarantee that shared bias is removed.')}</p>{mode==='demo'&&<Badge value="demo">{t('全部為合成模型','All synthetic models')}</Badge>}</div>{mode==='live'&&<div className="policy-fields"><Field label={t('程式資料政策','Code data policy')}><select value={dataPolicy} onChange={e=>{const value=e.target.value as 'local_only'|'cloud_allowed';setDataPolicy(value);setProbe({});if(value==='local_only')setModels(prev=>prev.map(m=>m.provider==='openai'||m.provider==='anthropic'?{...m,provider:'openai_compatible',model_id:'',family:'',endpoint:'http://127.0.0.1:11434/v1',credential_env:''}:m));}}><option value="local_only">{t('僅本地模型','Local models only')}</option><option value="cloud_allowed">{t('允許指定雲端模型','Named cloud models allowed')}</option></select></Field><Field label={t('允許的模型 origins','Allowed model origins')} hint={t('包含通訊協定、主機與埠；不包含 /v1 等路徑。','Include scheme, host and port; no path such as /v1.')}><textarea disabled={dataPolicy==='local_only'} value={origins} onChange={e=>setOrigins(e.target.value)} rows={2} placeholder={dataPolicy==='local_only'?t('本地政策由後端驗證端點','Under the local policy the backend validates endpoints'):'https://api.openai.com\nhttps://api.anthropic.com'}/></Field></div>}<div className="model-configs">{models.map((model,i)=><details className="model-config" key={model.id} open={mode==='live'}><summary><span className={`agent-avatar a${i}`}><Icon name={i===0?'shield':'chip'} size={18}/></span><div><strong>{ROLE_LABELS[model.role]}</strong><small>{PROVIDERS[model.provider]} · {model.model_id||t('尚未設定模型','No model configured yet')}</small></div><code>{model.id}</code><Icon name="chevron" size={15}/></summary><fieldset disabled={mode==='demo'}><div className="form-grid"><Field label={t('模型供應商','Model provider')}><select value={model.provider} onChange={e=>changeProvider(i,e.target.value as Provider)}>{mode==='demo'?<option value="demo">{t('本地合成示範','Local synthetic demo')}</option>:Object.entries(PROVIDERS).filter(([p])=>p!=='demo').map(([p,label])=><option key={p} value={p} disabled={dataPolicy==='local_only'&&['openai','anthropic'].includes(p)}>{label}</option>)}</select></Field><Field label={t('模型 ID','Model ID')}><input value={model.model_id} onChange={e=>updateModel(i,{model_id:e.target.value})} placeholder={t('填入端點提供的精確模型 ID','Enter the exact model ID the endpoint serves')}/></Field><Field label={t('模型家族','Model family')}><input value={model.family} onChange={e=>updateModel(i,{family:e.target.value})} placeholder={t('例如 claude / gpt / nemotron','For example claude / gpt / nemotron')}/></Field><Field label={t('API 端點','API endpoint')}><input value={model.endpoint} onChange={e=>updateModel(i,{endpoint:e.target.value})} placeholder="http://127.0.0.1:11434/v1"/></Field><Field label={t('金鑰的環境變數名稱','Key environment variable name')} hint={t('只填名稱；請勿貼上實際金鑰。金鑰只會送到操作者在 VIBEAUDIT_MODEL_CREDENTIAL_ORIGINS 綁定的 origin。','Name only; never paste the actual key. The key is sent only to the origin the operator binds in VIBEAUDIT_MODEL_CREDENTIAL_ORIGINS.')}><input value={model.credential_env} onChange={e=>updateModel(i,{credential_env:e.target.value})} autoComplete="off" spellCheck={false} placeholder={t('例如 VIBEAUDIT_OPENAI_API_KEY；本地可空白','For example VIBEAUDIT_OPENAI_API_KEY; may be blank for local')}/></Field><Field label={t('單次輸出 token 上限','Output token limit per call')}><input type="number" min={256} max={16000} value={model.max_output_tokens} onChange={e=>updateModel(i,{max_output_tokens:Number(e.target.value)})}/></Field><Field label="Temperature" hint={t('留空使用模型預設值；部分推理模型只接受預設值。','Leave blank for the model default; some reasoning models accept only the default.')}><input type="number" min={0} max={2} step={0.1} value={model.temperature??''} onChange={e=>updateModel(i,{temperature:e.target.value===''?null:Number(e.target.value)})} placeholder={t('模型預設','Model default')}/></Field></div>{mode==='live'&&<button className="button secondary small" type="button" disabled={!connected||probe[model.id]?.pending||!model.model_id||!model.endpoint} onClick={()=>void probeModel(model)}><Icon name="pulse" size={14}/>{probe[model.id]?.pending?t('檢查中…','Checking…'):t('檢查模型連線與能力','Check model connection and capabilities')}</button>}</fieldset>{mode==='live'&&<ModelPresetControls model={model} onLoad={profile=>updateModel(i,profile)}/>} {model.role!=='commander'&&model.role!=='reviewer'&&<button type="button" className="button secondary small" onClick={()=>setModels(models.filter(m=>m.id!==model.id))}>{t('移除此專責 Agent','Remove this dedicated agent')}</button>}{probe[model.id]?.message&&<div className={`probe-result ${probe[model.id].ok===false?'error':''}`} role="status"><SafeText value={probe[model.id].message}/></div>}</details>)}</div>{mode==='live'&&<div className="workspace-actions"><label className="field"><span>{t('選配專責 Agent','Optional dedicated agents')}</span><select value={specialRole} onChange={e=>setSpecialRole(e.target.value as ModelProfile['role'])}>{Object.entries(ROLE_LABELS).filter(([role])=>!['commander','reviewer'].includes(role)).map(([role,label])=><option key={role} value={role}>{label}</option>)}</select></label><button type="button" className="button secondary small" disabled={models.some(m=>m.role===specialRole)} onClick={()=>setModels([...models,{id:specialRole,role:specialRole,provider:'openai_compatible',model_id:'',family:'',endpoint:'',credential_env:'',temperature:0,max_output_tokens:3000}])}>{t('新增專責 Agent','Add dedicated agent')}</button></div>}{mode==='live'&&<p className="field-hint">{t('檢查模型可能產生供應商用量。模型探測結果不代表資安偵測品質；後端仍會執行正式預檢。','Checking a model may incur provider usage. A probe result says nothing about security detection quality; the backend still runs its own preflight.')}</p>}</Panel>
      <ExecutionSettings value={extensions} onChange={setExtensions} disabled={mode==='demo'}/><Panel title={t('補充需求','Additional requirements')} eyebrow="04 / CONTEXT">{mode==='live'&&<AuthProfilesEditor profiles={authProfiles} onChange={setAuthProfiles}/>}<Field label={t('評估備註','Assessment notes')} hint={t('業務安全條件、優先關注的功能，或目前已知限制。','Business security conditions, features to focus on, or known limits.')}><textarea value={notes} onChange={e=>setNotes(e.target.value)} rows={3} placeholder={t('例如：不同租戶不能存取彼此的客服紀錄。','For example: tenants must not access each other\'s support records.')}/></Field>{mode==='live'&&<details className="text-details"><summary>{t('進階：提供具明確 oracle 的測試案例','Advanced: provide test cases with explicit oracles')}</summary><p className="field-hint">{t('可貼上契約中的 Case JSON 陣列。後端會檢查威脅關聯、必要觀測、來源摘要與執行範圍；不完整案例不會自動通過。','Paste a JSON array of Cases from the contract. The backend checks threat links, required observations, source digest and execution scope; incomplete cases never pass automatically.')}</p><label className="sr-only" htmlFor="case-json">{t('自訂案例 JSON','Custom case JSON')}</label><textarea id="case-json" className="code-input" rows={8} value={caseText} onChange={e=>setCaseText(e.target.value)} placeholder="[]" spellCheck={false}/></details>}</Panel></div>
      <aside className="create-summary"><Panel title={t('執行預算','Run budget')} eyebrow="BOUND THE RUN"><div className="budget-fields">{([['max_seconds',t('時間上限','Time limit'),t('秒','s')],['max_requests',t('目標請求上限','Target request limit'),t('次','requests')],['max_model_calls',t('模型呼叫上限','Model call limit'),t('次','calls')],['max_tokens',t('模型 token 上限','Model token limit'),'tokens']] as const).map(([key,label,unit])=><Field label={label} key={key}><div className="input-unit"><input type="number" min={1} step={1} value={budget[key]} onChange={e=>setBudget({...budget,[key]:Number(e.target.value)})}/><span>{unit}</span></div></Field>)}</div><div className="summary-divider"/><div className="run-summary-row"><span>{t('模式','Mode')}</span><strong>{mode==='demo'?t('本地合成示範','Local synthetic demo'):t('實際資安評估','Live security assessment')}</strong></div><div className="run-summary-row"><span>{t('審查小組','Review panel')}</span><strong>{t('1 指揮官 + 3 審查員','1 commander + 3 reviewers')}</strong></div><div className="run-summary-row"><span>{t('測試順序','Test order')}</span><strong>{t('白箱 → 建模 → 黑箱','White-box → modeling → black-box')}</strong></div><div className="summary-divider"/><div className="summary-safety"><Icon name="lock" size={18}/><p>{mode==='demo'?t('示範只使用本地合成情境，不會呼叫設定中的外部服務。','The demo uses only local synthetic scenarios and never calls the external services in the settings.'):t('限你擁有或已獲授權的隔離 staging。範圍、威脅與案例都通過閘門後，才發送測試請求。','Only for isolated staging you own or are authorized to test. Test requests go out only after scope, threats and cases pass their gates.')}</p></div>{formError&&<div className="inline-warning" role="alert">{formError}</div>}<button type="submit" className="button primary create-submit" disabled={busy||!connected}>{busy?<><span className="spinner"/>{t('正在建立…','Creating…')}</>:<>{t('建立並開始','Create and start')}<Icon name="arrow" size={17}/></>}</button><p className="submit-note">{t('超出預算或證據不足時，會保留缺口並停止相應操作。','When the budget runs out or evidence is insufficient, the gap is kept and the related action stops.')}</p></Panel></aside>
    </form></>;
}
function Field({label,hint,children}: {label:string;hint?:string;children:ReactNode}) {return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;}
// The backend sends each limitation in English and, in the same order, in Chinese; fall back to English if they differ.
const limitationText=(source:{limitations:string[];limitations_zh?:string[]}|null)=>{const en=source?.limitations??[];const zh=source?.limitations_zh;return zh&&zh.length===en.length?en.map((text,i)=>t(zh[i],text)):en;};
function CapabilitiesView({capabilities,session}: {capabilities:Capabilities|null;session:Session|null}) {return <><div className="page-heading"><div><div className="eyebrow">HONEST CAPABILITIES</div><h1>{t('工具與執行環境','Tools and runtime')}</h1><p>{t('能力可用、受限或尚未實作，都由本地後端如實回報。','The local backend reports truthfully whether each capability is available, limited or not yet implemented.')}</p></div><span className="local-label"><Icon name="chip" size={17}/>{t('即時能力清單','Live capability list')}</span></div><div className="capabilities-grid">{capabilities?.tools.map(tool=><article className="capability-card" key={tool.id}><div><span className="tool-icon"><Icon name="chip"/></span><Badge value={tool.available?'completed':'blocked'}>{tool.available?t('可使用','Available'):t('尚不可使用','Not available yet')}</Badge></div><h3>{tool.id}</h3><p>{t(tool.detail,tool.detail_en??tool.detail)}</p><code>{tool.status}</code></article>)}</div>{!capabilities?.tools?.length&&<Empty title={t('尚無工具清單','No tool list yet')}>{t('確認本地服務連線，然後更新執行環境。','Check the local service connection, then refresh the runtime.')}</Empty>}<div className="detail-columns"><Panel title={t('已知限制','Known limitations')} eyebrow="LIMITATIONS"><ul className="limitations">{[...limitationText(session),...limitationText(capabilities)].filter((v,i,a)=>a.indexOf(v)===i).map((text,i)=><li key={i}><Icon name="alert" size={16}/><span>{text}</span></li>)}</ul></Panel><Panel title={t('執行環境資訊','Runtime information')} eyebrow="RUNTIME"><SafeText value={capabilities?.runtime??{}}/></Panel></div></>;}
